// marshalOnboardingOnboardingProviderToOnboardingProviderResponseBody builds a
// value of type *OnboardingProviderResponseBody from a value of type
// *onboarding.OnboardingProvider.
func marshalOnboardingOnboardingProviderToOnboardingProviderResponseBody(v *onboarding.OnboardingProvider) *OnboardingProviderResponseBody {
	res := &OnboardingProviderResponseBody{
		Slug: v.Slug,
		Name: v.Name,
	}
	if v.Plans != nil {
		res.Plans = make([]*OnboardingPlanResponseBody, len(v.Plans))
		for i, val := range v.Plans {
			if val == nil {
				res.Plans[i] = nil
				continue
			}
			res.Plans[i] = marshalOnboardingOnboardingPlanToOnboardingPlanResponseBody(val)
		}
	} else {
		res.Plans = []*OnboardingPlanResponseBody{}
	}
	if v.Products != nil {
		res.Products = make([]*OnboardingProductResponseBody, len(v.Products))
		for i, val := range v.Products {
			if val == nil {
				res.Products[i] = nil
				continue
			}
			res.Products[i] = marshalOnboardingOnboardingProductToOnboardingProductResponseBody(val)
		}
	} else {
		res.Products = []*OnboardingProductResponseBody{}
	}

	return res
}

